	    					//-------------------------------------email

	    					public byte[] BRRS_M_SRWA_12AEmailExcel(String filename, String reportId, String fromdate, String todate, String currency,
	    							String dtltype, String type, String format, BigDecimal version) throws Exception {

	    					    logger.info("Service: Starting Excel generation process in memory.");

	    					    if ("ARCHIVAL".equalsIgnoreCase(type) && version != null) {
	    					        try {
	    					            // Redirecting to Archival
	    					            return BRRS_M_SRWA_12AARCHIVALEmailExcel(filename, reportId, fromdate, todate, currency, dtltype, type,format, version);
	    					        } catch (ParseException e) {
	    					            logger.error("Invalid report date format: {}", fromdate, e);
	    					            throw new RuntimeException("Date format must be dd-MMM-yyyy (e.g. 31-Jul-2025)");
	    					        }

	    					    } else if ("RESUB".equalsIgnoreCase(type) && version != null) {

	    					        logger.info("Service: Generating RESUB report for version {}", version);

	    					        try {
	    					            // Redirecting to Resub Excel
	    					            return BRRSM_SRWA_12AEmailResubExcel(filename, reportId, fromdate, todate, currency, dtltype, type,format, version);

	    					        } catch (ParseException e) {
	    					            logger.error("Invalid report date format: {}", fromdate, e);
	    					            throw new RuntimeException("Date format must be dd-MMM-yyyy (e.g. 31-Jul-2025)");
	    					        }

	    					    } else {

	    					    	// Fetch data
	    					    	List<M_SRWA_12A_Summary_Entity1> dataList = getSummary1DataByDate(dateformat.parse(todate));

	    					    	List<M_SRWA_12A_Summary_Entity2> dataList1 = getSummary2DataByDate(dateformat.parse(todate));

	    					    	List<M_SRWA_12A_Summary_Entity3> dataList2 = getSummary3DataByDate(dateformat.parse(todate));

	    					    	List<M_SRWA_12A_Summary_Entity4> dataList3 = getSummary4DataByDate(dateformat.parse(todate));

	    					    	List<M_SRWA_12A_Summary_Entity5> dataList4 = getSummary5DataByDate(dateformat.parse(todate));

	    					    	List<M_SRWA_12A_Summary_Entity6> dataList5 = getSummary6DataByDate(dateformat.parse(todate));

	    					    	List<M_SRWA_12A_Summary_Entity7> dataList6 = getSummary7DataByDate(dateformat.parse(todate));

	    					    	List<M_SRWA_12A_Summary_M_Entity> dataList7 = getSummaryMDataByDate(dateformat.parse(todate));

	    					        if (dataList.isEmpty() && dataList1.isEmpty() && dataList2.isEmpty() &&
	    					            dataList3.isEmpty() && dataList4.isEmpty() && dataList5.isEmpty() &&
	    					            dataList6.isEmpty() && dataList7.isEmpty()) {

	    					            logger.warn("Service: No data found for M_SRWA_12A report. Returning empty result.");
	    					            return new byte[0];
	    					        }

	    					        String templateDir = env.getProperty("output.exportpathtemp");
	    					        String templateFileName = filename;

	    					        Path templatePath = Paths.get(templateDir, templateFileName);

	    					        logger.info("Service: Attempting to load template from path: {}", templatePath.toAbsolutePath());

	    					        if (!Files.exists(templatePath)) {
	    					            throw new FileNotFoundException("Template file not found at: " + templatePath.toAbsolutePath());
	    					        }

	    					        if (!Files.isReadable(templatePath)) {
	    					            throw new SecurityException(
	    					                    "Template file exists but is not readable (check permissions): " + templatePath.toAbsolutePath());
	    					        }

	    					        try (InputStream templateInputStream = Files.newInputStream(templatePath);
	    					             Workbook workbook = WorkbookFactory.create(templateInputStream);
	    					             ByteArrayOutputStream out = new ByteArrayOutputStream()) {

	    					            Sheet sheet = workbook.getSheetAt(0);

	    					            CreationHelper createHelper = workbook.getCreationHelper();

	    					            CellStyle dateStyle = workbook.createCellStyle();
	    					            dateStyle.setDataFormat(createHelper.createDataFormat().getFormat("dd-MM-yyyy"));
	    					            dateStyle.setBorderBottom(BorderStyle.THIN);
	    					            dateStyle.setBorderTop(BorderStyle.THIN);
	    					            dateStyle.setBorderLeft(BorderStyle.THIN);
	    					            dateStyle.setBorderRight(BorderStyle.THIN);

	    					            CellStyle textStyle = workbook.createCellStyle();
	    					            textStyle.setBorderBottom(BorderStyle.THIN);
	    					            textStyle.setBorderTop(BorderStyle.THIN);
	    					            textStyle.setBorderLeft(BorderStyle.THIN);
	    					            textStyle.setBorderRight(BorderStyle.THIN);

	    					            Font font = workbook.createFont();
	    					            font.setFontHeightInPoints((short) 8);
	    					            font.setFontName("Arial");

	    					            CellStyle numberStyle = workbook.createCellStyle();
	    					            numberStyle.setBorderBottom(BorderStyle.THIN);
	    					            numberStyle.setBorderTop(BorderStyle.THIN);
	    					            numberStyle.setBorderLeft(BorderStyle.THIN);
	    					            numberStyle.setBorderRight(BorderStyle.THIN);
	    					            numberStyle.setFont(font);

	    					            if (!dataList.isEmpty()) {
	    					                emailpopulateEntity1Data(sheet, dataList.get(0), textStyle, numberStyle,dateStyle);
	    					            }

	    					            if (!dataList1.isEmpty()) {
	    					                emailpopulateEntity2Data(sheet, dataList1.get(0), textStyle, numberStyle);
	    					            }

	    					            if (!dataList2.isEmpty()) {
	    					                emailpopulateEntity3Data(sheet, dataList2.get(0), textStyle, numberStyle);
	    					            }

	    					            if (!dataList3.isEmpty()) {
	    					                emailpopulateEntity4Data(sheet, dataList3.get(0), textStyle, numberStyle);
	    					            }

	    					            if (!dataList4.isEmpty()) {
	    					                emailpopulateEntity5Data(sheet, dataList4.get(0), textStyle, numberStyle);
	    					            }

	    					            if (!dataList5.isEmpty()) {
	    					                emailpopulateEntity6Data(sheet, dataList5.get(0), textStyle, numberStyle);
	    					            }

	    					            if (!dataList6.isEmpty()) {
	    					                emailpopulateEntity7Data(sheet, dataList6.get(0), textStyle, numberStyle);
	    					            }

	    					            if (!dataList7.isEmpty()) {
	    					                emailpopulateEntity8Data(sheet, dataList7.get(0), textStyle, numberStyle);
	    					            }

	    					            workbook.setForceFormulaRecalculation(true);
	    					            workbook.write(out);

	    					            logger.info("Service: Excel data successfully written to memory buffer ({} bytes).", out.size());
	    					            
	    					         // audit service summary email

	    					            ServletRequestAttributes attrs = (ServletRequestAttributes) RequestContextHolder.getRequestAttributes();
	    					            					if (attrs != null) {
	    					            						HttpServletRequest request = attrs.getRequest();
	    					            						String userid = (String) request.getSession().getAttribute("USERID");
	    					            						auditService.createBusinessAudit(userid, "DOWNLOAD", "M_SRWA_12A EMAIL SUMMARY", null, "BRRS_M_SRWA_12A_SUMMARYTABLE");
	    					            					}

	    					            return out.toByteArray();
	    					        }
	    					    }
	    					}



